import * as d3 from "d3";

const width = {width};
const height = {height};
const svg = d3.select({selector}).attr("viewBox", [0, 0, width, height].join(" "));
const x = d3.scaleBand().domain({data}.map(item => item.{labelProperty})).range([0, width]).padding(0.1);
const y = d3.scaleLinear().domain([0, d3.max({data}, item => item.{valueProperty}) ?? 0]).nice().range([height, 0]);

svg.selectAll("rect")
  .data({data})
  .join("rect")
  .attr("x", item => x(item.{labelProperty}) ?? 0)
  .attr("y", item => y(item.{valueProperty}))
  .attr("width", x.bandwidth())
  .attr("height", item => height - y(item.{valueProperty}));
